/*
 * This file is part of OpenBGI (https://openbgi.net).
 * SPDX-License-Identifier: GPL-2.0-only
 *
 * tests/picture.c - unit test of the picture files of "90 C4" / "90 C5"
 *                   (src/core/picture.c, src/core/jpeg.c, declared in
 *                   inc/bgi/picture.h, and their use in src/gfx/bmpload.c);
 *                   built as bin/test_picture by `make test`
 *
 * The embedded files were made by another library (the IJG codec through
 * Pillow) from one 16 x 16 gradient: the same picture baseline, with a
 * restart interval after every MCU, and progressive.  The three hold the
 * same coefficients, so they have to decode to the same pixels.
 *
 * The groups of tests, in the order they run:
 *
 *   jpeg      - the three embedded files decode alike and close to the
 *               gradient; the writer's file decodes close to its source,
 *               a grey-free picture's kind is 24-bit colour
 *   bmp png   - the 24-bit writers round-trip exactly; an 8-bit RLE BMP
 *               made here gives its indices and palette colours
 *   gif       - the embedded GIF: its indices, palette colours and the
 *               transparent index
 *   reject    - files that are none of the formats, or cut short
 *   opcodes   - BmpOp_SavePicture / BmpOp_LoadPicture as "90 C5" / "90 C4"
 *               use them: every format and mode, the result codes, the
 *               RGB32 relabel of mode 1, the GRAY8 rows taken from
 *               4-byte aligned rows
 *
 * The opcodes group writes files under bin/, so the test runs from the
 * project root (as `make test` does).
 */
#include "bgi/picture.h"
#include "bgi/gfx/bitmap.h"
#include "bgi/gfx/bmpmgr.h"
#include "bgi/gfx/bmpops.h"
#include "bgi/os.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int gFails; // the number of failed checks so far
// evaluate a condition; print it with its location and count a failure when it is false
#define CHECK(c)                                                  \
	do                                                            \
	{                                                             \
		if(!(c))                                                  \
		{                                                         \
			printf("  FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); \
			gFails++;                                             \
		}                                                         \
	} while(0)

