// the gradient the JPEG files were made from: R = x * 16, G = y * 16, B = 255 - (x + y) * 8
static int Gradient(int x, int y, int c)
{
	return c == 2 ? x * 16 : c == 1 ? y * 16
									: 255 - (x + y) * 8;
}

// the largest difference of a decoded picture's colour from the gradient
static int GradientError(const Picture_t* p)
{
	int x, y, c, worst = 0;
	for(y = 0; y < 16; y++)
		for(x = 0; x < 16; x++)
			for(c = 0; c < 3; c++)
			{
				int d = p->bgra[(y * 16 + x) * 4 + c] - Gradient(x, y, c);
				if(d < 0)
					d = -d;
				if(d > worst)
					worst = d;
			}
	return worst;
}

// ---- JPEG ---------------------------------------------------------------------------

/* The baseline, restart and progressive files decode to the same pixels,
 * 16 x 16 24-bit colour, opaque, within 20 levels of the gradient (the
 * files are of quality 50).  The writer at quality 90 on a 37 x 29 picture (MCUs cut at
 * both edges) decodes within a few levels of its source; its file is a
 * baseline JFIF.  A failure means a Huffman, progressive or restart path,
 * the transform or the colour conversion changed. */
static void TestJpeg(void)
{
	Picture_t a, r, p, e;
	uint8_t src[37 * 29 * 4];
	uint8_t* file;
	size_t size = 0;
	int x, y, worst = 0;
	printf("jpeg\n");
	CHECK(Picture_Decode(kJpegBase, sizeof kJpegBase, &a));
	CHECK(Picture_Decode(kJpegRst, sizeof kJpegRst, &r));
	CHECK(Picture_Decode(kJpegProg, sizeof kJpegProg, &p));
	CHECK(a.width == 16 && a.height == 16 && a.kind == PIC_RGB24 && !a.index && a.bgra[3] == 0xFF);
	CHECK(r.bgra && memcmp(a.bgra, r.bgra, 16 * 16 * 4) == 0);
	CHECK(p.bgra && memcmp(a.bgra, p.bgra, 16 * 16 * 4) == 0);
	CHECK(GradientError(&a) <= 20); // (17, as the IJG decoder gives as well)
	Picture_Free(&a);
	Picture_Free(&r);
	Picture_Free(&p);
	for(y = 0; y < 29; y++)
		for(x = 0; x < 37; x++)
		{
			uint8_t* o = src + (y * 37 + x) * 4;
			o[0] = (uint8_t)(x * 6);
			o[1] = (uint8_t)(y * 8);
			o[2] = (uint8_t)(200 - x * 2 - y * 2);
			o[3] = 0x12; // ignored
		}
	file = Jpeg_Encode(src, 37, 29, 37 * 4, 90, &size);
	CHECK(file && size > 600 && file[0] == 0xFF && file[1] == 0xD8 && memcmp(file + 6, "JFIF", 5) == 0);
	CHECK(file && file[size - 2] == 0xFF && file[size - 1] == 0xD9);
	CHECK(file && Picture_Decode(file, size, &e) && e.width == 37 && e.height == 29 && e.kind == PIC_RGB24);
	if(e.bgra)
		for(x = 0; x < 37 * 29 * 4; x++)
			if((x & 3) != 3)
			{
				int d = abs(e.bgra[x] - src[x]);
				if(d > worst)
					worst = d;
			}
	CHECK(worst <= 8);
	Picture_Free(&e);
	BGI_Free(file);
}

// ---- BMP and PNG -------------------------------------------------------------------

/* The 24-bit BMP and PNG writers give back their source exactly, opaque,
 * as 24-bit colour.  An 8-bit RLE BMP of 3 x 2 (a run, a literal pair, an
 * end of line, a delta of one column, a run, the end of the bitmap: rows
 * from the bottom) gives the indices and their palette colours, the pixel
 * the delta skipped index 0.  A failure means a writer or the BMP
 * reader's row order, palette or RLE changed. */
static void TestBmpPng(void)
{
	uint8_t src[5 * 3 * 4], rle[54 + 4 * 4 + 16];
	uint8_t* file;
	size_t size = 0;
	Picture_t p;
	int i, pass;
	printf("bmp png\n");
	for(i = 0; i < 5 * 3 * 4; i++)
		src[i] = (uint8_t)(i * 37 + 11);
	for(pass = 0; pass < 2; pass++)
	{
		file = pass ? Png_Encode24(src, 5, 3, 20, &size) : Bmp_Encode24(src, 5, 3, 20, &size);
		CHECK(file && Picture_Decode(file, size, &p) && p.width == 5 && p.height == 3 && p.kind == PIC_RGB24);
		for(i = 0; p.bgra && i < 15; i++)
			if(memcmp(p.bgra + i * 4, src + i * 4, 3) != 0 || p.bgra[i * 4 + 3] != 0xFF)
				break;
		CHECK(i == 15);
		Picture_Free(&p);
		BGI_Free(file);
	}
	memset(rle, 0, sizeof rle);
	rle[0] = 'B', rle[1] = 'M', rle[10] = 54 + 16, rle[14] = 40;
	rle[18] = 3, rle[22] = 2, rle[26] = 1, rle[28] = 8, rle[30] = 1, rle[46] = 4; // 3 x 2, 8 bpp, RLE8, 4 colours
	for(i = 0; i < 4; i++)
	{ // colour i: B = i, G = 0x10 * i, R = 0x40
		rle[54 + i * 4] = (uint8_t)i;
		rle[54 + i * 4 + 1] = (uint8_t)(0x10 * i);
		rle[54 + i * 4 + 2] = 0x40;
	}
	{
		static const uint8_t data[16] = {0, 3, 3, 2, 1, 0, 0, 0, 0, 2, 1, 0, 2, 1, 0, 1};
		// bottom row: the literal 3 2 1 (padded to a whole word); end of line;
		// top row: a delta of one column, a run of 2 x index 1; end of bitmap
		memcpy(rle + 70, data, 16);
	}
	CHECK(Picture_Decode(rle, sizeof rle, &p) && p.width == 3 && p.height == 2 && p.kind == PIC_INDEXED8 && p.index);
	if(p.index)
	{
		static const uint8_t want[6] = {0, 1, 1, 3, 2, 1};
		CHECK(memcmp(p.index, want, 6) == 0);
		CHECK(p.bgra[3 * 4] == 3 && p.bgra[3 * 4 + 1] == 0x30 && p.bgra[3 * 4 + 2] == 0x40 && p.bgra[3 * 4 + 3] == 0xFF);
	}
	Picture_Free(&p);
}

// ---- GIF ----------------------------------------------------------------------------

/* The embedded 4 x 3 GIF: palette black, red, green, blue, index 2
 * transparent.  A failure means the LZW decoder, the palette or the
 * transparency of the graphic control extension changed. */
static void TestGif(void)
{
	static const uint8_t want[12] = {0, 1, 2, 3, 3, 2, 1, 0, 1, 1, 2, 2};
	Picture_t p;
	int i, bad = 0;
	printf("gif\n");
	CHECK(Picture_Decode(kGif, sizeof kGif, &p) && p.width == 4 && p.height == 3 && p.kind == PIC_INDEXED8);
	CHECK(p.index && memcmp(p.index, want, 12) == 0);
	for(i = 0; p.bgra && i < 12; i++)
	{
		const uint8_t* o = p.bgra + i * 4;
		int k = want[i];
		if(o[2] != (k == 1 ? 255 : 0) || o[1] != (k == 2 ? 255 : 0) || o[0] != (k == 3 ? 255 : 0) || o[3] != (k == 2 ? 0 : 255))
			bad++;
	}
	CHECK(bad == 0);
	Picture_Free(&p);
}

/* Not a picture, or cut short before its first scan: no picture.  A
 * failure means a reader accepts something it cannot have read. */
static void TestReject(void)
{
	Picture_t p;
	printf("reject\n");
	CHECK(!Picture_Decode((const uint8_t*)"not a picture", 13, &p));
	CHECK(!Picture_Decode(kJpegBase, 300, &p)); // the headers, but no scan yet
	CHECK(!Picture_Decode(kGif, 12, &p));
	CHECK(!Picture_Decode((const uint8_t*)"BM", 2, &p));
}

// ---- the opcodes' functions -------------------------------------------------------

static void Spit(const char* path, const void* data, size_t n)
{
	FILE* f = fopen(path, "wb");
	if(f)
	{
		fwrite(data, 1, n, f);
		fclose(f);
	}
}

/* "90 C5" / "90 C4" through BmpOp_SavePicture / BmpOp_LoadPicture: an
 * ARGB32 bitmap saved as PNG (format 4) and BMP (0) comes back exactly
 * and opaque with mode 2, as RGB32 with mode 1, by mode -1 as RGB32 (a
 * 24-bit file); JPEG (1) close.  Saving: 3 without a bitmap, 4 for a
 * format above 4, 5 for GIF / TIFF and a quality above 100.  Loading: -1
 * for a missing file with an explicit mode, 0x80000001 / 0x80000002 with
 * mode -1 for a missing / unreadable file, -1 for mode 0 and for a colour
 * picture as GRAY8; the embedded GIF as GRAY8 with mode 3 and by mode -1,
 * its 4-pixel rows unchanged; a 5-pixel-wide 8-bit BMP as GRAY8 takes
 * its indices out of 8-byte rows as if they were packed. */
static void TestOpcodes(void)
{
	static const char* path = "bin/test_picture_tmp";
	Bmp_t b, l;
	int x, y, ok;
	printf("opcodes\n");
	gBmpOption = 0;
	gBmpMgr = BmpMgr_New(4);
	CHECK(BmpMgr_Create(gBmpMgr, 0, 7, 5, PM_ARGB32));
	BmpMgr_GetInfo(gBmpMgr, &b, 0);
	for(y = 0; y < 5; y++)
		for(x = 0; x < 7; x++)
		{
			uint8_t* p = b.pixels + y * b.pitch + x * 4;
			p[0] = (uint8_t)(x * 30), p[1] = (uint8_t)(y * 50), p[2] = (uint8_t)(x * y * 5), p[3] = (uint8_t)(x * 20);
		}
	CHECK(BmpOp_SavePicture(3, path, 4, 0) == (int)0x80000003u);
	CHECK(BmpOp_SavePicture(0, path, 5, 0) == (int)0x80000004u);
	CHECK(BmpOp_SavePicture(0, path, 2, 0) == (int)0x80000005u);
	CHECK(BmpOp_SavePicture(0, path, 3, 0) == (int)0x80000005u);
	CHECK(BmpOp_SavePicture(0, path, 1, 101) == (int)0x80000005u);
	for(x = 0; x < 2; x++)
	{
		CHECK(BmpOp_SavePicture(0, path, x ? 0u : 4u, 0) == 0);
		CHECK(BmpOp_LoadPicture(1, path, 2) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 1) && l.mode == PM_ARGB32 && l.w == 7 && l.h == 5);
		for(y = 0, ok = 1; y < 5 * 7; y++)
		{
			const uint8_t* s = b.pixels + (y / 7) * b.pitch + (y % 7) * 4;
			const uint8_t* d = l.pixels + (y / 7) * l.pitch + (y % 7) * 4;
			if(memcmp(s, d, 3) != 0 || d[3] != 0xFF)
				ok = 0;
		}
		CHECK(ok);
		CHECK(BmpOp_LoadPicture(1, path, 1) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 1) && l.mode == PM_RGB32);
		CHECK(BmpOp_LoadPicture(2, path, -1) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 2) && l.mode == PM_RGB32);
		CHECK(BmpOp_LoadPicture(2, path, 3) == -1); // colour as indices
		CHECK(BmpOp_LoadPicture(2, path, 0) == -1);
	}
	CHECK(BmpOp_SavePicture(0, path, 1, 90) == 0);
	CHECK(BmpOp_LoadPicture(1, path, 2) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 1) && l.w == 7 && l.h == 5);
	remove(path);
	CHECK(BmpOp_LoadPicture(1, path, 2) == -1);
	CHECK(BmpOp_LoadPicture(1, path, -1) == (int)0x80000001u);
	Spit(path, "garbage", 7);
	CHECK(BmpOp_LoadPicture(1, path, -1) == (int)0x80000002u);
	CHECK(BmpOp_LoadPicture(1, path, 2) == -1);
	Spit(path, kGif, sizeof kGif);
	CHECK(BmpOp_LoadPicture(1, path, 3) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 1) && l.mode == PM_GRAY8 && l.w == 4);
	CHECK(l.pixels && l.pixels[0] == 0 && l.pixels[3] == 3 && l.pixels[l.pitch] == 3 && l.pixels[2 * l.pitch + 3] == 2);
	CHECK(BmpOp_LoadPicture(2, path, -1) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 2) && l.mode == PM_GRAY8);
	{ // 5 x 2, 8 bpp uncompressed: indices row 0 = 10 .. 14, row 1 = 20 .. 24
		uint8_t f[54 + 256 * 4 + 16];
		int i;
		memset(f, 0, sizeof f);
		f[0] = 'B', f[1] = 'M', f[10] = (uint8_t)((54 + 1024) & 0xff), f[11] = (uint8_t)((54 + 1024) >> 8), f[14] = 40;
		f[18] = 5, f[22] = 2, f[26] = 1, f[28] = 8;
		for(i = 0; i < 5; i++)
		{
			f[54 + 1024 + i] = (uint8_t)(20 + i);     // the bottom row first
			f[54 + 1024 + 8 + i] = (uint8_t)(10 + i); // (rows of 8 bytes)
		}
		Spit(path, f, sizeof f);
		CHECK(BmpOp_LoadPicture(1, path, 3) == 0 && BmpMgr_GetInfo(gBmpMgr, &l, 1) && l.w == 5 && l.h == 2);
		// the rows were taken out of rows of 8 bytes as if packed: the second row starts at the first row's padding
		CHECK(l.pixels && l.pixels[0] == 10 && l.pixels[4] == 14 && l.pixels[l.pitch] == 0 && l.pixels[l.pitch + 3] == 20);
	}
	remove(path);
	BmpMgr_Delete(gBmpMgr);
	gBmpMgr = NULL;
}

// run every group; exit status 1 when any check failed
int main(void)
{
	OS_Init();
	TestJpeg();
	TestBmpPng();
	TestGif();
	TestReject();
	TestOpcodes();
	OS_Shutdown();
	if(gFails)
	{
		printf("%d failure(s)\n", gFails);
		return 1;
	}
	printf("ok\n");
	return 0;
}
